      return `复核读数 ${correctedEndValue} 小于当期期初读数 ${span.startValue}，表具累计读数不能倒退`;
    }
    if (next && correctedEndValue > next.endValue) {
      return `复核读数 ${correctedEndValue} 大于次期期末读数 ${next.endValue}，与后续抄表记录矛盾`;
    }
    return null;
  }
}

