  ) {}

  /** 照片访问控制：仅照片所属读数对应的表主住户，或客服，可取原图 */
  async getAccessiblePhoto(photoId: number, userId: number, role: string) {
    const photo = await this.prisma.readingPhoto.findUnique({
      where: { id: photoId },
      include: { reading: { include: { meter: true } } },
