  @Get('meter/:meterId/readings')
  curve(
    @Param('meterId', ParseIntPipe) meterId: number,
    @CurrentUser() user: { id: number; role: string },
  ) {
    return this.bills.readingCurve(meterId, user.id, user.role);
  }
}

