input.content:
:root {
  color-scheme: light;
  --surface-1: #fcfcfb;
  --page: #f9f9f7;
  --text-primary: #0b0b0b;
  --text-secondary: #52514e;
  --text-muted: #898781;
  --gridline: #e1e0d9;
  --baseline: #c3c2b7;
  --border: rgba(11, 11, 11, 0.1);
  --series-actual: #2a78d6; /* 实抄：蓝 slot 1 */
  --series-estimated: #eb6834; /* 估抄：橙 slot 2 */
  --good: #0ca30c;
  --good-text: #006300;
  --warning-bg: #fdf3dd;
  --warning-text: #8a5a00;
  --critical-bg: #fbe9e9;
  --critical-text: #a52727;
  --info-bg: #e8f1fc;
  --info-text: #1c5cab;
  --refund: #006300;
  --surcharge: #a52727;
  --card-shadow: 0 1px 2px rgba(11, 11, 11, 0.05), 0 2px 8px rgba(11, 11, 11, 0.04);
}

* { box-sizing: border-box; }
html, body, #root { height: 100%; margin: 0; }
body {
  font-family: system-ui, -apple-system, 'Segoe UI', 'PingFang SC', 'Microsoft YaHei', sans-serif;
  background: var(--page);
  color: var(--text-primary);
  font-size: 14px;
  line-height: 1.55;
}

button { font-family: inherit; }

.login-wrap {
  min-height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}
.login-card {
  width: 380px;
  background: var(--surface-1);
  border: 1px solid var(--border);
  border-radius: 12px;
  box-shadow: var(--card-shadow);
  padding: 28px;
}
.login-card h1 { font-size: 18px; margin: 0 0 4px; }
.login-card .sub { color: var(--text-secondary); font-size: 13px; margin-bottom: 20px; }
.login-hint {
  margin-top: 16px;
  padding: 10px 12px;
  background: var(--page);
  border-radius: 8px;
  font-size: 12px;
  color: var(--text-secondary);
  white-space: pre-line;
}

.field { margin-bottom: 14px; }
.field label { display: block; font-size: 13px; color: var(--text-secondary); margin-bottom: 5px; }
.field input, .field textarea, .field select {
  width: 100%;
  padding: 9px 11px;
  border: 1px solid var(--baseline);
  border-radius: 8px;
  background: #fff;
  color: var(--text-primary);
  font-size: 14px;
  font-family: inherit;
}
.field textarea { resize: vertical; min-height: 72px; }
.field input:focus, .field textarea, .field select:focus { outline: 2px solid rgba(42, 120, 214, 0.25); border-color: var(--series-actual); }

.btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 14px;
  border-radius: 8px;
  border: 1px solid var(--baseline);
  background: #fff;
  color: var(--text-primary);
  font-size: 13px;
  cursor: pointer;
}
.btn:hover { background: var(--page); }
.btn:disabled { opacity: 0.5; cursor: not-allowed; }
.btn-primary { background: var(--series-actual); border-color: var(--series-actual); color: #fff; }
.btn-primary:hover { background: #256abf; }
.btn-danger { color: var(--critical-text); border-color: #e4b7b7; }
.btn-danger:hover { background: var(--critical-bg); }
.btn-sm { padding: 5px 10px; font-size: 12px; }

.app-shell { display: flex; flex-direction: column; min-height: 100%; }
.topbar {
  background: var(--surface-1);
  border-bottom: 1px solid var(--border);
  padding: 0 24px;
  height: 56px;
  display: flex;
  align-items: center;
  gap: 24px;
}
.brand { font-weight: 700; font-size: 15px; }
.tabs { display: flex; gap: 4px; flex: 1; }
.tab {
  padding: 7px 14px;
  border-radius: 8px;
  border: none;
  background: transparent;
  color: var(--text-secondary);
  cursor: pointer;
  font-size: 14px;
}
.tab:hover { background: var(--page); }
.tab.active { background: var(--info-bg); color: var(--info-text); font-weight: 600; }
.userbox { display: flex; align-items: center; gap: 10px; font-size: 13px; color: var(--text-secondary); }
.userbox .role {
  font-size: 11px;
  padding: 2px 8px;
  border-radius: 99px;
  background: var(--info-bg);
  color: var(--info-text);
}

.page { padding: 24px; max-width: 1100px; width: 100%; margin: 0 auto; }
.page-head { display: flex; align-items: baseline; justify-content: space-between; margin-bottom: 16px; gap: 12px; flex-wrap: wrap; }
.page-head h2 { margin: 0; font-size: 18px; }
.page-head .desc { color: var(--text-secondary); font-size: 13px; }

.card {
  background: var(--surface-1);
  border: 1px solid var(--border);
  border-radius: 12px;
  box-shadow: var(--card-shadow);
  padding: 18px 20px;
  margin-bottom: 16px;
}
.card h3 { margin: 0 0 12px; font-size: 15px; }

.badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
