  padding: 12px 14px;
  background: #fff;
}
.stat .k { font-size: 12px; color: var(--text-muted); margin-bottom: 4px; }
.stat .v { font-size: 20px; font-weight: 700; }
.stat .v.refund { color: var(--refund); }
.stat .v.surcharge { color: var(--surcharge); }

.delta-refund { color: var(--refund); font-weight: 600; }
.delta-surcharge { color: var(--surcharge); font-weight: 600; }

.error-box {
  background: var(--critical-bg);
  color: var(--critical-text);
  border-radius: 8px;
  padding: 9px 12px;
  font-size: 13px;
  margin-bottom: 12px;
}
.ok-box {
  background: #e7f5e7;
  color: var(--good-text);
  border-radius: 8px;
  padding: 9px 12px;
  font-size: 13px;
  margin-bottom: 12px;
}
.muted { color: var(--text-muted); }
.small { font-size: 12px; }
.row-actions { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
.flow { display: flex; flex-direction: column; gap: 0; }
.flow-item {
  display: grid;
  grid-template-columns: 28px 1fr;
  gap: 8px;
  position: relative;
  padding-bottom: 18px;
}
.flow-item:not(:last-child)::before {
  content: '';
  position: absolute;
  left: 9px;
  top: 18px;
  bottom: 2px;
  width: 2px;
  background: var(--gridline);
}
.flow-dot {
  width: 20px; height: 20px;
  border-radius: 50%;
  background: var(--info-bg);
  color: var(--info-text);
  display: flex; align-items: center; justify-content: center;
  font-size: 11px;
  z-index: 1;
}
.flow-item.done .flow-dot { background: #d8ec d8; }
.flow-body .t { font-weight: 600; font-size: 13px; }
.flow-body .m { color: var(--text-secondary); font-size: 12px; margin-top: 2px; }

.modal-mask {
  position: fixed; inset: 0;
  background: rgba(11, 11, 11, 0.35);
  display: flex; align-items: flex-start; justify-content: center;
  padding: 40px 20px;
  z-index: 50;
  overflow-y: auto;
}
.modal {
  background: var(--surface-1);
  border-radius: 12px;
  width: 720px;
  max-width: 100%;
  padding: 22px 24px;
  box-shadow: 0 12px 40px rgba(11, 11, 11, 0.2);
}
.modal h3 { margin: 0 0 4px; font-size: 16px; }
.modal .modal-sub { color: var(--text-secondary); font-size: 13px; margin-bottom: 14px; }
.modal-actions { display: flex; justify-content: flex-end; gap: 10px; margin-top: 18px; }

.kv { display: grid; grid-template-columns: 110px 1fr; gap: 6px 12px; font-size: 13px; }
.kv .k { color: var(--text-muted); }

.photo-thumb {
  border: 1px solid var(--gridline);
  border-radius: 8px;
  overflow: hidden;
  width: 168px;
  background: #fff;
  cursor: zoom-in;
}
.photo-thumb img { width: 100%; display: block; }
.photo-thumb .cap { font-size: 11px; color: var(--text-muted); padding: 5px 7px; border-top: 1px solid var(--gridline); }
.photo-grid { display: flex; gap: 12px; flex-wrap: wrap; margin-top: 8px; }

.notice-bar {
  border: 1px solid #e7d8b3;
  background: #fdf8ea;
  color: #6e5310;
  border-radius: 10px;
  padding: 10px 14px;
  font-size: 13px;
  margin-bottom: 14px;
}

/* 读数曲线 */
.chart-wrap { margin: 8px 0 4px; }
.chart-legend { display: flex; gap: 18px; align-items: center; font-size: 12px; color: var(--text-secondary); margin-bottom: 6px; }
.legend-item { display: inline-flex; align-items: center; gap: 6px; }
.legend-swatch { width: 10px; height: 10px; border-radius: 50%; }
.chart-svg { display: block; width: 100%; height: auto; }
.chart-svg text { font-family: inherit; }
.chart-tooltip {
  position: fixed;
  pointer-events: none;
  background: #1f2937;
  color: #fff;
  padding: 7px 10px;
  border-radius: 8px;
  font-size: 12px;
  z-index: 100;
  white-space: nowrap;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.25);
}
.chart-tooltip .tt-title { font-weight: 700; margin-bottom: 2px; }

