    const rect = e.currentTarget.getBoundingClientRect();
    const scaleX = W / rect.width;
    const mx = (e.clientX - rect.left) * scaleX;
    let best = 0;
    let bestDist = Infinity;
    periods.forEach((_, i) => {
      const d = Math.abs(xOf(i) - mx);
      if (d < bestDist) {
        bestDist = d;
        best = i;
      }
    });
    const period = periods[best];
