import { useEffect, useState } from 'react';
import { api } from '../api';
import { Dispute, UserInfo } from '../types';
import { DISPUTE_STATUS_LABEL, periodLabel, signedYuan, statusTone, yuan } from '../format';
import { Modal } from '../components/Modal';
import { DisputePanel } from '../components/DisputePanel';

export function DisputesPage({ user }: { user: UserInfo }) {
  const [disputes, setDisputes] = useState<Dispute[]>([]);
  const [openId, setOpenId] = useState<number | null>(null);
  const [residents, setResidents] = useState<{ id: number; displayName: string }[]>([]);
  const [residentFilter, setResidentFilter] = useState<number | ''>('');
  const [loading, setLoading] = useState(true);

  const load = async () => {
    setLoading(true);
    const query = user.role === 'AGENT' && residentFilter ? `?residentId=${residentFilter}` : '';
    setDisputes(await api<Dispute[]>('GET', `/disputes${query}`));
    setLoading(false);
  };

  useEffect(() => {
    load();
    if (user.role === 'AGENT') {
      api<any[]>('GET', '/bills').then((bills) => {
        const map = new Map<number, { id: number; displayName: string }>();
        // 客服账单列表不含住户名，改由异议列表汇聚；若为空则无下拉
        void map;
      });
    }
  }, [residentFilter]);

  return (
    <div className="page">
      <div className="page-head">
        <h2>{user.role === 'AGENT' ? '异议复核工作台' : '我的异议'}</h2>
