              <th className="num">调整净额（元）</th>
              <th>状态</th>
              <th>更新时间</th>
            </tr>
          </thead>
          <tbody>
            {loading ? (
              <tr><td colSpan={8} className="muted">加载中…</td></tr>
            ) : disputes.length === 0 ? (
              <tr><td colSpan={8} className="muted">暂无异议申请。</td></tr>
