const { chromium } = require('playwright-core');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  const errors = [];
  page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
  page.on('pageerror', (e) => errors.push(String(e)));

  // ---- 住户视图 ----
  await page.goto('http://localhost:5173');
  await page.fill('input[type="text"], input:not([type])', 'zhang');
  await page.fill('input[type="password"]', 'resident123');
  await page.click('button[type="submit"]');
  await page.waitForSelector('text=我的账单');
  await page.screenshot({ path: '/tmp/shot/01-bills.png', fullPage: true });

  // 打开 2026-08 账单详情（已被冒烟脚本调整：估抄210→实抄190，退款+补收）
  await page.click('tr.clickable:has-text("2026 年 8 月")');
  await page.waitForSelector('.chart-svg');
  await page.waitForTimeout(600);
  await page.screenshot({ path: '/tmp/shot/02-bill-detail.png', fullPage: true });

  // 悬停 8 月位置触发 tooltip（横轴约第 3/4 位置）
  const box = await page.locator('.chart-svg').boundingBox();
  await page.mouse.move(box.x + box.width * 0.72, box.y + box.height * 0.5);
  await page.waitForTimeout(300);
  await page.screenshot({ path: '/tmp/shot/03-chart-tooltip.png' });

  await page.keyboard.press('Escape');
  await page.click('text=我的异议');
  await page.waitForTimeout(500);
  await page.click('tr.clickable:has-text("2026 年 8 月")');
  await page.waitForTimeout(500);
  await page.screenshot({ path: '/tmp/shot/04-dispute-panel.png', fullPage: true });

  await page.keyboard.press('Escape');
  await page.click('text=费用流水');
  await page.waitForTimeout(400);
  await page.screenshot({ path: '/tmp/shot/05-ledger.png', fullPage: true });

  // ---- 客服视图 ----
  await page.click('text=退出');
  await page.fill('input:not([type])', 'agent');
  await page.fill('input[type="password"]', 'agent123');
  await page.click('button[type="submit"]');
  await page.waitForSelector('text=异议复核工作台');
  await page.waitForTimeout(400);
  await page.screenshot({ path: '/tmp/shot/06-agent-workbench.png', fullPage: true });

  console.log('console errors:', errors.length ? errors : 'none');
  await browser.close();
})();

